"""Explain origin packing, half-open ranges, report offsets and task setup."""
import json
from rewrite_c_beginner import rewrite, ROOT
ROWS={'os1717': ('작은 기록에 숫자와 예·아니요 표시를 함께 넣으려 해요. 맨 아래 한 칸은 표시용으로 비워 두고 숫자를 한 칸 위로 옮기면 서로 겹치지 않아요.', '깊이와 해제 후 사용 표시를 비트에 나눠 넣고 꺼내는 방법을 이해합니다.', '깊이3을 이진수11로 적고 한 칸 밀어110, UAF1을 붙여111=7을 만드세요. 다시 깊이3·표시1을 꺼내세요.', ['origin은 준비되지 않은 값의 원인을 추적하는 기록과 연결돼요. depth는 원인 연결의 깊이이고 UAF는 use-after-free, 즉 해제한 메모리를 나중에 사용하는 문제와 관련된 표시예요. extra bits는 기록 식별자에 덧붙이는 작은 정보 칸이에요.', 'kmsan_extra_bits의 식은 (depth<<1)|uaf예요. <<1은 비트를 왼쪽으로 한 칸 옮기는 것이에요. 작은 정상 범위의 수에서는 두 배를 하는 것과 같고 맨 아래 칸이0으로 비어요. 거기에 참·거짓인 uaf를 넣어요.', '깊이3은 이진수11이에요. 한 칸 옮기면110, 숫자6이 돼요. uaf가1이면 OR 기호 |로 맨 아래 칸을 켜서111, 숫자7이 돼요. uaf가0이면110 그대로6이에요. 깊이7·표시1이면1110에1을 붙여1111, 숫자15예요.', '다시 꺼낼 때 extra&1은 맨 아래 칸만 골라 UAF 표시를 얻어요. extra>>1은 맨 아래 칸을 버리고 나머지를 오른쪽으로 옮겨 깊이를 얻어요. extra7이면7&1=1,7>>1=3이어서 처음 두 정보를 되찾아요.', '이 helper에는 깊이가7보다 큰지 확인하거나 min(depth,7)로 줄이는 코드가 없어요. clamp는 값을 정해진 한도 안으로 제한하는 일이에요. 이 함수는 이동과 OR만 하므로 한도 처리가 자동으로 여기에 있다고 생각하면 안 돼요.', '실제 허용 깊이와 저장 가능한 extra bit 수는 호출 코드와 stack depot의 저장 규칙도 함께 봐야 해요. 이 수업에서0~7을 계산했다고 임의의 큰 수를 넣어도 정확히 보존된다는 뜻은 아니에요. 제한된 칸에 압축할 때는 입력 범위도 약속의 일부예요.'], [('depth=3,uaf=1이면 extra 값은 얼마인가요?', ['3이에요', '7이에요'], '정답은 두 번째예요. 3<<1은6이고 아래 빈 칸에1을 넣으면7이에요. 원래 깊이3을 그대로 반환하면 UAF 표시를 따로 담을 자리가 없어요.'), ('kmsan_extra_bits 자체가 깊이를 최대7로 줄여 주나요?', ['아니요. 본문은 shift와 OR만 해요', '네. 내부에서 min(depth,7)을 계산해요'], '정답은 첫 번째예요. 비트 배치와 값의 한도 처리는 별도 단계예요. 실제 저장 함수와 호출자가 지키는 깊이 조건도 확인해야 해요.')]), 'os1718': ('100번부터200번 앞까지라는 구역이 있어요. 100번은 안에 있고200번은 다음 구역이에요. 구역 번호 안에 들어온다고 그 자리에 실제 집이 있다는 것까지 알 수는 없어요.', '시작을 포함하고 끝을 제외하는 주소 구간과 실제 메모리 연결을 구별합니다.', '시작100·끝200인 연습 구역에서99,100,199,200의 포함 여부를 아니요·예·예·아니요로 적으세요.', ['커널은 주소가 어느 용도의 영역에 있는지 분류할 때가 있어요. module은 필요에 따라 추가하는 커널 코드와 관련되고 vmalloc은 가상 주소 공간에 메모리를 마련하는 방식과 관련돼요. 두 helper는 주소 숫자가 각 영역의 경계 안에 있는지 비교해요.', '주소를 u64, 즉64비트 부호 없는 숫자로 바꾸어 시작 이상인지와 끝 미만인지 확인해요. module은 MODULES_VADDR 이상이고 MODULES_END 미만이어야 해요. vmalloc도 VMALLOC_START 이상이고 VMALLOC_END 미만이라는 같은 모양의 식이에요.', '>=는 경계값을 포함하는 이상이고 <는 경계값을 제외하는 미만이에요. 예를 들어 시작100·끝200이면100부터199까지 포함하고200은 제외해요. 이렇게 시작만 포함하고 끝은 빼는 구간을 반열린 구간이라고 불러요.', '99는 시작 전이라 실패,100은 시작이므로 통과,199는 끝보다 작아서 통과,200은 끝과 같아 실패예요. 끝 주소 자체를 포함한다고 읽으면 바로 다음 영역의 첫 위치를 잘못 넣을 수 있어요. 실제 주소 상수 대신 작은 숫자로 경계 기호를 연습한 예예요.', '이 함수들은 KMSAN runtime에서 다시 검사 hook으로 돌아가는 재귀를 피하려고 비계측 버전으로 둔다고 원문이 설명해요. 비계측은 검사 코드가 다시 붙어 자기 자신을 부르는 문제를 피하는 데 관련된 말이에요. 주소 분류 자체가 새 메모리를 할당하는 일은 아니에요.', '주소가 숫자 구역 안에 있다는 것과 실제 메모리 페이지에 연결되어 있다는 것은 달라요. mapping은 가상 주소를 실제 저장 공간과 연결하는 것이고 PFN은 물리 페이지 번호예요. 이 helper는 그 페이지의 존재나 유효성을 모두 검사하지 않으므로 후속 페이지 조회와 검사도 필요해요.'], [('MODULES_END 주소 자체도 module 범위에 들어가나요?', ['네. 시작과 끝을 모두 포함해요', '아니요. 끝은 < 비교라서 제외해요'], '정답은 두 번째예요. 본문은 주소<MODULES_END예요. 시작은 포함하지만 끝과 같은 주소는 통과하지 않아요.'), ('숫자 주소가 구역 안이면 실제 페이지도 유효하다고 확인됐나요?', ['아니요. 페이지 연결과 유효성 확인은 별도예요', '네. 구역 안의 모든 숫자에 반드시 메모리가 있어요'], '정답은 첫 번째예요. 주소 분류는 숫자 경계 비교예요. 실제 페이지가 있는지까지 알아보는 함수는 아니므로 후속 조회를 구별해야 해요.')]), 'os1719': ('한 줄의 칸에서 같은 원인으로 생긴 문제끼리 묶어 보고해요. 앞부분은 원인A, 뒷부분은 원인B라면 하나의 줄에서도 보고가 두 번 나올 수 있어요.', '전체 검사 범위와 원인별 연속 보고 구간을 구별합니다.', '주소100부터8칸에 offset0~7을 쓰세요. 원인77인1~2칸, 원인88인5~7칸을 따로 묶고 각 길이2·3을 계산하세요.', ['kmsan_report는 준비되지 않은 값을 사용한 문제를 보고하는 인터페이스예요. origin은 그 문제의 원인 기록을 가리켜요. 같은 원인을 가진 연속된 바이트들을 한 그룹으로 설명할 수 있어요. 연속은 중간에 떨어진 칸 없이 이어진다는 뜻이에요.', 'address와 size는 검사한 접근의 시작 주소와 전체 길이예요. off_first와 off_last는 그 시작에서 보고할 그룹의 첫 칸과 마지막 칸까지 얼마나 떨어져 있는지 나타내요. 이렇게 시작으로부터 떨어진 정도를 offset이라고 부르며 첫 칸은0부터 세어요.', '시작 주소100·전체 길이8이라면 칸 주소는100~107, offset은0~7이에요. 원인77인 문제가 offset1~2에 있으면 실제 주소101~102 두 칸이에요. off_first=1,off_last=2이고 길이는2-1+1=2예요. 마지막 offset과 길이는 서로 다른 값이에요.', '원인88인 다른 그룹이 offset5~7에 있으면 같은 address100과 size8을 사용하면서 원인88·시작5·끝7로 따로 보고할 수 있어요. 이 그룹의 길이는7-5+1=3이에요. 한 범위를 검사했다고 보고도 반드시 한 번만 나오는 것은 아니에요.', 'reason은 오류 종류를 구별하는 값이에요. REASON_ANY, 사용자 공간 복사와 관련된 REASON_COPY_TO_USER, USB 전송 요청 제출과 관련된 REASON_SUBMIT_URB가 있어요. user_addr가 NULL이 아니면 커널 데이터가 나가는 사용자 쪽 주소를 나타낸다고 설명돼 있어요.', '원문에는 준비되지 않은 값을 비교 연산에서 사용한 경우 주소를 지정하지 않고 한 번 호출하는 계약도 있어요. 따라서 모든 호출이 주소가 있는 범위 검사와 똑같다고 가정하면 안 돼요. 이 수업은 함수 인자와 그룹 의미를 설명하며 실제 출력 형식과 호출 기록 해석은 보고 구현에서 더 읽어야 해요.'], [('한 번 검사한 범위에서도 원인이 다른 그룹을 여러 번 보고할 수 있나요?', ['아니요. 전체 검사마다 보고는 반드시 한 번이에요', '네. 전체 주소·길이는 같아도 원인과 offset을 달리해 보고할 수 있어요'], '정답은 두 번째예요. 예를 들어 offset1~2의 원인77과5~7의 원인88을 따로 보고할 수 있어요. 전체 요청 범위와 각 보고 그룹의 범위를 구별하세요.'), ('off_last는 무엇인가요?', ['보고할 마지막 바이트의 offset이에요', '언제나 그룹의 바이트 수예요'], '정답은 첫 번째예요. offset5~7인 그룹의 off_last는7이지만 길이는3이에요. 양끝을 포함하므로 길이는 끝-시작+1로 계산해요.')]), 'os1720': ('공책의 실제 내용을0으로 채우는 일과 검사표에 준비 완료 표시를 하는 일은 달라요. 이 함수는 두 대상을 골라 두 종류의 처리를 해요.', '문맥의 실제 초기화와 thread 정보의 검사 상태 표시를 구별합니다.', 'task→kmsan_ctx에는 실제0쓰기, current_thread_info()→info에는 검사 상태 준비됨 표시를 연결해 그리세요.', ['kmsan_internal_task_create는 작업 생성과 관련해 KMSAN 상태를 준비하는 함수예요. task는 인자로 받은 대상 작업이에요. 먼저 ctx를 &task->kmsan_ctx로 정해서 그 작업의 검사 문맥을 가리키게 해요.', '별도로 info는 current_thread_info()에서 얻어요. current는 지금 실행 중인 작업과 관련된 말이에요. task에서 얻은 ctx와 현재 실행 쪽에서 얻은 info를 같은 주소라고 추측하면 안 돼요. 원문에서 두 대상의 출처가 다르다는 점을 먼저 표시해 보세요.', '__memset(ctx,0,sizeof(*ctx))는 ctx가 가리키는 문맥의 실제 바이트를 모두0으로 써요. sizeof(*ctx)는 포인터 변수 크기가 아니라 가리키는 문맥 구조체 전체 크기예요. 따라서 이 줄은 검사 표시만 바꾸는 것이 아니라 실제 상태를 초기화해요.', '다음 kmsan_internal_unpoison_memory(info,sizeof(*info),false)는 thread_info 범위의 검사 상태를 준비된 것으로 표시해요. unpoison은 값을0으로 채우는 명령이 아니에요. info의 실제 데이터와 그 데이터에 붙은 검사 상태를 구별해야 해요.', '마지막 false는 checked라는 인자의 값이에요. 이 호출은 검사를 요구하는 checked 경로를 선택하지 않는다는 뜻이며 초기화 표시를 취소하라는 뜻이 아니에요. unpoison 구현은 내부 상태 설정 함수에 shadow값0과 origin값0을 전달해요.', '순서는 대상 문맥 선택·현재 thread 정보 선택·문맥 실제0쓰기·thread 정보의 검사 상태 표시예요. 서로 다른 대상과 동작을 모두 초기화라는 한 단어로만 읽으면 놓치는 부분이 생겨요. 이 작은 함수가 전체 작업 생성이나 fork 과정 모두를 수행하는 것도 아니에요.'], [('이 함수는 task의 검사 문맥에 실제로0을 쓰나요?', ['아니요. 검사표만 바꿔요', '네. __memset으로 문맥의 실제 바이트를0으로 채워요'], '정답은 두 번째예요. __memset(ctx,0,sizeof(*ctx))가 있어요. 뒤의 thread_info unpoison과는 대상과 동작이 다르므로 구별해야 해요.'), ('unpoison할 thread_info 주소는 어디서 얻나요?', ['current_thread_info()에서 얻어요', '항상 task 인자를 바이트 주소로 바꿔서 얻어요'], '정답은 첫 번째예요. info의 초기값을 만드는 줄을 보면 current_thread_info()예요. task->kmsan_ctx를 고르는 줄과 별개이므로 두 포인터를 같은 것으로 합치면 안 돼요.')])}
def run():
    additions={}
    for path in (ROOT/'course/lesson-parts').glob('*.json'):
        for lesson in json.loads(path.read_text(encoding='utf-8')):
            key=lesson['id']
            if key not in ROWS:continue
            practice=dict(lesson.get('practice',{}));practice['expected']=ROWS[key][2]
            additions[key]=dict(concepts=[],reading_support=None,deep_dive=[],goal=ROWS[key][1],experiment={'title':'종이에 따라 해 보기','steps':[ROWS[key][2]]},practice=practice)
    return rewrite(ROWS,'tools/rewrite_os_beginner_425.py',additions)
if __name__=='__main__':print(json.dumps(run(),ensure_ascii=False))
